-- Preserve the original repair; use the pinned shared terminal check.
do $historical_dual$
declare completion_recognized boolean;completion_passed boolean;
begin
  lock table public.content_update in share mode;
  lock table public.content_source in share mode;
  lock table public.ability_block in share row exclusive mode;
  lock table public.ancestry in share row exclusive mode;
  lock table public.archetype in share row exclusive mode;
  lock table public.class in share row exclusive mode;
  lock table public.creature in share row exclusive mode;
  lock table public.item in share row exclusive mode;
  lock table public.language in share row exclusive mode;
  lock table public.spell in share row exclusive mode;
  lock table public.trait in share row exclusive mode;
  perform s.id from public.content_source s where s.id in(1,3,7,8,11,12,13,14,15,16,17,18,19,22,23,28,29,33,34,37,51,185,239,240,241,256,400,420,476,493,842) order by s.id for share;
  if (exists(select 1 from pg_catalog.pg_proc p
  where p.oid=pg_catalog.to_regprocedure('public.treasure_vault_terminal_status_v1()')
    and pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to((p.prosrc)::text,'UTF8')),'hex')='18134f9ceb5b974368dcfba9e6a145c839b63a762014424005872665b4dce869'
    and p.prokind='f' and p.prolang=(select l.oid from pg_catalog.pg_language l where l.lanname='sql')
    and p.provolatile='s' and p.prosecdef is false and p.proisstrict is false and p.proleakproof is false
    and p.proparallel='u' and p.procost=100 and p.prorows=1
    and p.pronargs=0 and p.pronargdefaults=0 and p.proretset is true
    and p.prorettype=pg_catalog.to_regtype('record')
    and p.proallargtypes=array[pg_catalog.to_regtype('boolean')::oid,pg_catalog.to_regtype('boolean')::oid]
    and p.proargmodes=array['t','t']::"char"[] and p.proargnames=array['recognized','passed']::text[]
    and p.proconfig=array['search_path=""']::text[] and p.proowner=pg_catalog.to_regrole('postgres')
    and (select count(*)=3
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('postgres'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('service_role'))=1
      and count(*) filter(where a.grantee=pg_catalog.to_regrole('supabase_read_only_user'))=1
      and bool_and((a.privilege_type='EXECUTE' and a.is_grantable is false
      and a.grantor=pg_catalog.to_regrole('postgres')
      and a.grantee in(pg_catalog.to_regrole('postgres'),pg_catalog.to_regrole('service_role'),pg_catalog.to_regrole('supabase_read_only_user'))) is true)
      from pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a)
    and pg_catalog.has_function_privilege('postgres',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE')
    and pg_catalog.has_function_privilege('supabase_read_only_user',p.oid,'EXECUTE'))) is not true then
    raise exception 'Treasure Vault terminal helper is missing or differs from the reviewed definition';
  end if;
  select s.recognized,s.passed into strict completion_recognized,completion_passed from public.treasure_vault_terminal_status_v1() s;
  if completion_recognized is null or completion_passed is null then
    raise exception 'Treasure Vault terminal helper returned an invalid status';
  end if;
  if completion_recognized then
    if completion_passed is not true then raise exception 'Treasure Vault catalog/display successor is partial or unreviewed';end if;
    return;
  end if;
  execute $historical_original_dual$-- Add the five published Treasure Vault relic seeds.
do $missing$
declare
  spec jsonb := $seeds$
{"items":[{"name":"Fortune's Favor","uuid":"944653220160268","row":{"name":"Fortune's Favor","bulk":"0","level":3,"rarity":"UNIQUE","description":"**Aspects** luck and mind\n\n* * *\n\nBlessed by Nivi Rhombodazzle, this striking silver necklace is adorned with sparkling sapphires that draw the eye of any who see it. Over the years, this necklace has appeared in many paintings and illustrations, usually around the neck of a carefree and daring adventurer or a stylish rake gambling vast sums of coin. Finding this [relic](link_trait_3460) is always seen as a sign of great fortune to come, but when that luck runs out, the necklace is lost just as quickly.\n\nWearing the [relic](link_trait_3460), you quickly realize how distracting it can be, granting you a +1 item bonus on Deception checks made to [Feint](link_action_19633) and on Games Lore checks made to gamble or determine the outcome of a game of chance.\n\n* * *\n\n**Minor Gifts** [beginner's luck](link_feat_29695), [whammy](link_feat_29697)\n\n**Major Gifts** [clean luck](link_feat_29698), [perception filter](link_feat_29712)\n\n**Grand Gift** [against all odds](link_feat_29700)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"worn","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"204","url":"https://2e.aonprd.com/Equipment.aspx?ID=2406"}},"operations":[{"id":"c013f74b-c390-486c-8af2-898799d53f4d","type":"addBonusToValue","data":{"variable":"SKILL_DECEPTION","value":1,"type":"item","text":"to Feint"}}],"content_source_id":16,"version":"1.0","uuid":944653220160268,"price":null,"traits":[1460,1527,1504,3460],"availability":null},"metadata_absent":["deprecated","base_item","base_item_content","category","group","damage","runes","attack_bonus","ac_bonus","range","reload","hp","hardness","container_default_items","display_traits","inventory_label"]},{"name":"Inventor's Chair","uuid":"8452974248299523","row":{"name":"Inventor's Chair","bulk":"3","level":4,"rarity":"UNIQUE","description":"**Aspects** artistry and emotion (dedication)\n\n* * *\n\nInitially crafted by a gifted inventor who no longer had the use of their legs, the inventor's chair is a [traveler's chair](link_item_7904). It's a marvel of engineering, utilizing clockwork mechanisms to maneuver about. The chair comes equipped with [wheel blades](link_item_15502), and portions of its frame contain [sterling artisan's tools](link_item_6724). The inventor's chair might be a family heirloom or a gift from someone who inherited it. It could instead sit unused in its inventor's abandoned estate, awaiting another user.\n\n* * *\n\n**Minor Gifts** [emotion surge](link_feat_29512), [muse](link_feat_28851) (Crafting)\n\n**Major Gifts** [emotion conduit](link_feat_29514), [enthralling](link_feat_28853)\n\n**Grand Gift** [artistic perfection](link_feat_28854) (Crafting)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"205","url":"https://2e.aonprd.com/Equipment.aspx?ID=2407"}},"operations":[{"id":"5378776c-43b7-4c2c-b4cf-77fe30319050","type":"addBonusToValue","data":{"variable":"SKILL_CRAFTING","value":1,"type":"item","text":"to Craft items using the integrated artisan's toolkit"}}],"content_source_id":16,"version":"1.0","uuid":8452974248299523,"price":null,"traits":[1504,3460],"availability":null},"metadata_absent":["deprecated","base_item","base_item_content","category","group","damage","runes","attack_bonus","ac_bonus","range","reload","hp","hardness","container_default_items","display_traits","inventory_label"]},{"name":"Phistophilus Fiddle","uuid":"2231238570519876","row":{"name":"Phistophilus Fiddle","bulk":"1","level":3,"rarity":"UNIQUE","description":"**Aspects** artistry and fiend\n\n* * *\n\nMade of pure gold with platinum strings, the phistophilus fiddle shouldn't be able to play a note, but play it does, so beautifully that it can move almost any audience. The fiddle was stolen from the [contract devil](link_creature_10242) who created it, and the cunning fiend still wants to reclaim the instrument. Fiendish misfortunes often befall its owners, allowing it to switch hands. The fiddle is a handheld [virtuoso instrument](link_item_7604).\n\n* * *\n\n**Minor Gifts** [little helper](link_feat_29519), [muse](link_feat_28851) (Performance)\n\n**Major Gifts** [charming](link_feat_28852), [fiendish bargain](link_feat_29520)\n\n**Grand Gift** [artistic perfection](link_feat_28854) (Performance)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"held in 2 hands","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"205","url":"https://2e.aonprd.com/Equipment.aspx?ID=2408"}},"operations":[{"id":"6dc958e0-89f2-426c-974c-bc779962143a","type":"addBonusToValue","data":{"variable":"SKILL_PERFORMANCE","value":1,"type":"item","text":"while playing the phistophilus fiddle"}}],"content_source_id":16,"version":"1.0","uuid":2231238570519876,"price":null,"traits":[1504,3460],"availability":null},"metadata_absent":["deprecated","base_item","base_item_content","category","group","damage","runes","attack_bonus","ac_bonus","range","reload","hp","hardness","container_default_items","display_traits","inventory_label"]},{"name":"Sleuth's Pipe","uuid":"8338913217540863","row":{"name":"Sleuth's Pipe","bulk":"0.1","level":3,"rarity":"UNIQUE","description":"**Aspects** luck and mind\n\n* * *\n\nA famed detective once owned the long, curved sleuth's pipe, taking it with them on investigations, keeping it in hand or mouth while cogitating. The pipe might have passed down through generations. Or, when an owner dies without heirs, it could go up for auction, be given to family friends, or remain at the scene of a crime to be found later. The sleuth's pipe has sapience that eventually awakens, allowing the [relic](link_trait_3460) to act as a helpful assistant in investigations.\n\nEven while this sapience sleeps within the pipe, it grants you a +1 item bonus to Perception checks to [Sense Motive](link_action_19847), and if you're an [investigator](link_class_110), any checks you make to [Pursue a Lead](link_feat_30995).\n\n* * *\n\n**Minor Gifts** [beginner's luck](link_feat_29695), [repository of knowledge](link_feat_29711)\n\n**Major Gifts** [intelligent relic](link_feat_29688), [steal luck](link_feat_29699)\n\n**Grand Gift** [mental bastion](link_feat_29714)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"held in 1 hand","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"205","url":"https://2e.aonprd.com/Equipment.aspx?ID=2409"}},"operations":[{"id":"a04a4b05-53c8-47b5-81fc-b89bcf38aff8","type":"addBonusToValue","data":{"variable":"PERCEPTION","value":1,"type":"item","text":"to Sense Motive"}}],"content_source_id":16,"version":"1.0","uuid":8338913217540863,"price":null,"traits":[1504,3460],"availability":null},"metadata_absent":["deprecated","base_item","base_item_content","category","group","damage","runes","attack_bonus","ac_bonus","range","reload","hp","hardness","container_default_items","display_traits","inventory_label"]},{"name":"Watch of Lost Ages","uuid":"8797079847352829","row":{"name":"Watch of Lost Ages","bulk":"0.1","level":3,"rarity":"UNIQUE","description":"**Aspects** emotion (misery) and time\n\n* * *\n\nThe origins of the watch of lost ages, a silver pocket watch, are enigmatic. Its construction matches no known culture, and its appearance shifts back and forth from battered and tarnished to shiny and new without cause or apparent reason. The watch exudes a sense of melancholy and loss, and anyone holding it is acutely aware of the impermanence of all things and the march of time, moving ever forward.\n\nThis [relic](link_trait_3460) might show up in a mysterious ruin or spontaneously appear in a spellcaster's hand after they cast a [time](link_trait_4185) spell. The [relic](link_trait_3460) grants you a +1 item bonus to [Recall Knowledge](link_action_19753) about historical subjects.\n\n* * *\n\n**Minor Gifts** [fervor](link_feat_29513), [sands of the hourglass](link_feat_29806)\n\n**Major Gifts** [fervent spell](link_feat_29515), [temporal pulse](link_feat_29808)\n\n**Grand Gift** [time reversal](link_feat_29810)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"held in 1 hand","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"205","url":"https://2e.aonprd.com/Equipment.aspx?ID=2410"}},"operations":[],"content_source_id":16,"version":"1.0","uuid":8797079847352829,"price":null,"traits":[1504,3460],"availability":null},"metadata_absent":["deprecated","base_item","base_item_content","category","group","damage","runes","attack_bonus","ac_bonus","range","reload","hp","hardness","container_default_items","display_traits","inventory_label"]}],"dependencies":[{"table":"trait","queue_type":"trait","id":3460,"name":"Relic","uuid":"2735161210254535","source":7,"expected":{"id":3460,"name":"Relic","uuid":"2735161210254535","content_source_id":7},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"ability_block","queue_type":"ability-block","id":19633,"name":"Feint","uuid":"4994199721560613","source":3,"expected":{"id":19633,"name":"Feint","uuid":"4994199721560613","content_source_id":3,"type":"action"},"metadata":{},"metadata_absent":["deprecated","unselectable","hidden"]},{"