$seeds$::jsonb;
  successor_spec jsonb := $successor${"seeds":[{"name":"Fortune's Favor","bulk":"0","level":3,"rarity":"UNIQUE","description":"**Aspects** luck and mind\n\n* * *\n\nBlessed by Nivi Rhombodazzle, this striking silver necklace is adorned with sparkling sapphires that draw the eye of any who see it. Over the years, this necklace has appeared in many paintings and illustrations, usually around the neck of a carefree and daring adventurer or a stylish rake gambling vast sums of coin. Finding this [relic](link_trait_3460) is always seen as a sign of great fortune to come, but when that luck runs out, the necklace is lost just as quickly.\n\nWearing the [relic](link_trait_3460), you quickly realize how distracting it can be, granting you a +1 item bonus on Deception checks made to [Feint](link_action_19633) and on Games Lore checks made to gamble or determine the outcome of a game of chance.\n\n* * *\n\n**Minor Gifts** [beginner's luck](link_feat_29695), [whammy](link_feat_29697)\n\n**Major Gifts** [clean luck](link_feat_29698), [perception filter](link_feat_29712)\n\n**Grand Gift** [against all odds](link_feat_29700)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"worn","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"204","url":"https://2e.aonprd.com/Equipment.aspx?ID=2406"}},"operations":[{"id":"c013f74b-c390-486c-8af2-898799d53f4d","type":"addBonusToValue","data":{"variable":"SKILL_DECEPTION","value":1,"type":"item","text":"to Feint"}}],"content_source_id":16,"version":"1.0","uuid":944653220160268,"price":null,"traits":[1460,1527,1504,3460],"availability":null},{"name":"Inventor's Chair","bulk":"3","level":4,"rarity":"UNIQUE","description":"**Aspects** artistry and emotion (dedication)\n\n* * *\n\nInitially crafted by a gifted inventor who no longer had the use of their legs, the inventor's chair is a [traveler's chair](link_item_7904). It's a marvel of engineering, utilizing clockwork mechanisms to maneuver about. The chair comes equipped with [wheel blades](link_item_15502), and portions of its frame contain [sterling artisan's tools](link_item_6724). The inventor's chair might be a family heirloom or a gift from someone who inherited it. It could instead sit unused in its inventor's abandoned estate, awaiting another user.\n\n* * *\n\n**Minor Gifts** [emotion surge](link_feat_29512), [muse](link_feat_28851) (Crafting)\n\n**Major Gifts** [emotion conduit](link_feat_29514), [enthralling](link_feat_28853)\n\n**Grand Gift** [artistic perfection](link_feat_28854) (Crafting)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"205","url":"https://2e.aonprd.com/Equipment.aspx?ID=2407"}},"operations":[{"id":"5378776c-43b7-4c2c-b4cf-77fe30319050","type":"addBonusToValue","data":{"variable":"SKILL_CRAFTING","value":1,"type":"item","text":"to Craft items using the integrated artisan's toolkit"}}],"content_source_id":16,"version":"1.0","uuid":8452974248299523,"price":null,"traits":[1504,3460],"availability":null},{"name":"Phistophilus Fiddle","bulk":"1","level":3,"rarity":"UNIQUE","description":"**Aspects** artistry and fiend\n\n* * *\n\nMade of pure gold with platinum strings, the phistophilus fiddle shouldn't be able to play a note, but play it does, so beautifully that it can move almost any audience. The fiddle was stolen from the [contract devil](link_creature_10242) who created it, and the cunning fiend still wants to reclaim the instrument. Fiendish misfortunes often befall its owners, allowing it to switch hands. The fiddle is a handheld [virtuoso instrument](link_item_7604).\n\n* * *\n\n**Minor Gifts** [little helper](link_feat_29519), [muse](link_feat_28851) (Performance)\n\n**Major Gifts** [charming](link_feat_28852), [fiendish bargain](link_feat_29520)\n\n**Grand Gift** [artistic perfection](link_feat_28854) (Performance)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"held in 2 hands","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"205","url":"https://2e.aonprd.com/Equipment.aspx?ID=2408"}},"operations":[{"id":"6dc958e0-89f2-426c-974c-bc779962143a","type":"addBonusToValue","data":{"variable":"SKILL_PERFORMANCE","value":1,"type":"item","text":"while playing the phistophilus fiddle"}}],"content_source_id":16,"version":"1.0","uuid":2231238570519876,"price":null,"traits":[1504,3460],"availability":null},{"name":"Sleuth's Pipe","bulk":"0.1","level":3,"rarity":"UNIQUE","description":"**Aspects** luck and mind\n\n* * *\n\nA famed detective once owned the long, curved sleuth's pipe, taking it with them on investigations, keeping it in hand or mouth while cogitating. The pipe might have passed down through generations. Or, when an owner dies without heirs, it could go up for auction, be given to family friends, or remain at the scene of a crime to be found later. The sleuth's pipe has sapience that eventually awakens, allowing the [relic](link_trait_3460) to act as a helpful assistant in investigations.\n\nEven while this sapience sleeps within the pipe, it grants you a +1 item bonus to Perception checks to [Sense Motive](link_action_19847), and if you're an [investigator](link_class_110), any checks you make to [Pursue a Lead](link_feat_30995).\n\n* * *\n\n**Minor Gifts** [beginner's luck](link_feat_29695), [repository of knowledge](link_feat_29711)\n\n**Major Gifts** [intelligent relic](link_feat_29688), [steal luck](link_feat_29699)\n\n**Grand Gift** [mental bastion](link_feat_29714)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"held in 1 hand","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"205","url":"https://2e.aonprd.com/Equipment.aspx?ID=2409"}},"operations":[{"id":"a04a4b05-53c8-47b5-81fc-b89bcf38aff8","type":"addBonusToValue","data":{"variable":"PERCEPTION","value":1,"type":"item","text":"to Sense Motive"}}],"content_source_id":16,"version":"1.0","uuid":8338913217540863,"price":null,"traits":[1504,3460],"availability":null},{"name":"Watch of Lost Ages","bulk":"0.1","level":3,"rarity":"UNIQUE","description":"**Aspects** emotion (misery) and time\n\n* * *\n\nThe origins of the watch of lost ages, a silver pocket watch, are enigmatic. Its construction matches no known culture, and its appearance shifts back and forth from battered and tarnished to shiny and new without cause or apparent reason. The watch exudes a sense of melancholy and loss, and anyone holding it is acutely aware of the impermanence of all things and the march of time, moving ever forward.\n\nThis [relic](link_trait_3460) might show up in a mysterious ruin or spontaneously appear in a spellcaster's hand after they cast a [time](link_trait_4185) spell. The [relic](link_trait_3460) grants you a +1 item bonus to [Recall Knowledge](link_action_19753) about historical subjects.\n\n* * *\n\n**Minor Gifts** [fervor](link_feat_29513), [sands of the hourglass](link_feat_29806)\n\n**Major Gifts** [fervent spell](link_feat_29515), [temporal pulse](link_feat_29808)\n\n**Grand Gift** [time reversal](link_feat_29810)","group":"GENERAL","hands":null,"size":"MEDIUM","craft_requirements":null,"usage":"held in 1 hand","meta_data":{"bulk":{},"charges":{},"image_url":"","is_shoddy":false,"unselectable":false,"starfinder":{},"quantity":1,"source":{"book":"Treasure Vault (Remastered)","page":"205","url":"https://2e.aonprd.com/Equipment.aspx?ID=2410"}},"operations":[],"content_source_id":16,"version":"1.0","uuid":8797079847352829,"price":null,"traits":[1504,3460],"availability":null}],"chair":{"item":{"name":"Animal Pseudopod","bulk":null,"level":0,"rarity":"COMMON","description":"An [agile](link_trait_1569) pseudopod attack.","group":"WEAPON","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"brawling","runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"d6","dice":1,"extra":"","damageType":"B"},"charges":{},"category":"unarmed_attack","material":{},"quantity":1,"image_url":"","is_shoddy":false,"unselectable":true,"source":{"book":"Treasure Vault (Remastered)","page":"106","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"operations":[],"content_source_id":16,"version":"1.0","uuid":3341821474558316,"price":{},"traits":[2398,1569],"availability":null},"creature":{"name":"Oozeform Chair","level":-100,"rarity":"COMMON","meta_data":{"source":{"book":"Treasure Vault (Remastered)","page":"106","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"content_source_id":16,"version":"1.0","uuid":722858796387375,"inventory":null,"notes":null,"details":{"description":"Your companion is an alchemical [ooze](link_trait_2448) that extends pseudopods to move around."},"roll_history":null,"operations":[{"id":"d116656e-d3f6-4e67-a0e5-00b890559d7b","type":"giveTrait","data":{"traitId":3842}},{"id":"0ba6dafd-abfe-4bb1-8b41-b32a344e53c3","type":"select","data":{"title":"Select a Size","modeType":"PREDEFINED","optionType":"CUSTOM","optionsPredefined":[{"id":"8ebcab10-ab0e-47d6-98d2-5b5ac112fb36","type":"CUSTOM","title":"Medium","description":"Their size is Medium.","operations":[{"id":"af736fda-6561-48cb-9b16-f2fea642c787","type":"setValue","data":{"variable":"SIZE","value":"medium"}}]},{"id":"f3334693-0aa6-40bf-b412-d7459e5f599c","type":"CUSTOM","title":"Large","description":"Their size is Large.","operations":[{"id":"250d6e79-2efc-4a9b-89ae-f1ffdc3ee015","type":"setValue","data":{"variable":"SIZE","value":"large"}}]}]}},{"id":"0658