2-a98b-858bbdc85ee4","data":{"value":{"value":-4,"partial":false},"variable":"ATTRIBUTE_INT"},"type":"setValue"},{"id":"544fd70f-a7ce-4c8e-a6a1-8c00b89a358a","type":"setValue","data":{"variable":"ATTRIBUTE_WIS","value":{"value":0,"partial":false}}},{"id":"ff093e12-8f91-4303-b83a-e8d0f3269903","type":"setValue","data":{"variable":"ATTRIBUTE_CHA","value":{"value":0,"partial":false}}},{"id":"038bf2bc-6408-422a-a5b4-250da3fb530e","type":"setValue","data":{"variable":"SPEED","value":20}},{"id":"d85a1f8e-a36b-4c34-ba83-01b58455e3e8","type":"giveItem","data":{"itemId":-30001}},{"id":"74f33cf5-8425-41b6-99de-d10beb25d886","type":"giveTrait","data":{"traitId":2448}},{"id":"426705a6-5429-4508-94b4-3aacb1e7381a","type":"giveTrait","data":{"traitId":2527}}],"abilities_base":[{"id":258023274553453,"created_at":"","operations":[{"id":"b8f21efd-d986-49e3-959b-e200b8d53794","type":"select","data":{"title":"Select Advancement","modeType":"PREDEFINED","optionType":"CUSTOM","optionsPredefined":[{"id":"d243dc01-803f-4252-86e7-4959b6eac200","type":"CUSTOM","title":"- Not Yet","description":"No next advancement yet.","operations":[]},{"id":"07ac7c4c-495c-4376-a1a4-27c87e2727cc","type":"CUSTOM","title":"Mature","description":"When you advance a young animal companion to a mature animal companion:\n\n*   If your companion is Medium or smaller, it grows by one size.\n    \n*   Increase its Strength, Dexterity, Constitution, and Wisdom modifiers by 1.\n    \n*   Increase its proficiency rank for Perception and all saving throws to expert. Increase its proficiency ranks in Intimidation, Stealth, and Survival to trained, and if it was already trained in one of those skills from its type, increase its proficiency rank in that skill to expert.\n    \n*   Increase its unarmed attack damage from one die to two dice (for instance 1d8 to 2d8)","operations":[{"id":"84e005c3-8a05-41f1-acad-a5688ee74c4f","type":"giveAbilityBlock","data":{"type":"feat","abilityBlockId":40304}}]}]}}],"name":"Next Advancement","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"You advance an animal companion, usually due to one of your class feat choices.","special":"","type":"action","meta_data":{},"traits":[],"content_source_id":16,"version":"1.0"},{"id":4302541392659529,"created_at":"","operations":[{"id":"9921ac76-0334-48bd-b661-0209da83b4dd","type":"adjValue","data":{"variable":"SENSES_IMPRECISE","value":"motion sense, 30"}}],"name":"Motion Sense","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"Your oozeform chair can sense nearby creatures through vibration in the air. This is an imprecise sense with a range of 30 feet.","special":"","type":"sense","meta_data":{"source":{"book":"Treasure Vault (Remastered)","page":"106","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"traits":[],"content_source_id":16,"version":"1.0"},{"id":3725444017242910,"created_at":"","operations":[],"name":"Mount","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"This companion is especially suited for riding and ignores the restrictions against using non-land Speeds and moving and Supporting you on the same turn while it is carrying a rider.","special":"","type":"action","meta_data":{"source":{"book":"Treasure Vault (Remastered)","page":"106","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"traits":[],"content_source_id":16,"version":"1.0"},{"id":7902105097017992,"created_at":"","operations":[],"name":"Support","actions":"ONE-ACTION","level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"The creature is an animal companion.","access":"","description":"A pseudopod extends out from your chair, retrieving an unattended object within 15 feet. If you don't have a hand free to receive the object, the chair drops it in your space.","special":"If the animal uses the Support action, the only other actions it can use on this turn are basic [move](link_trait_1505) actions to get into position to take advantage of the Support benefits; if it has already used any other action this turn, it can’t Support you.","type":"action","meta_data":{"source":{"book":"Treasure Vault (Remastered)","page":"106","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"traits":[],"content_source_id":16,"version":"1.0"},{"id":4322909037039800,"created_at":"","operations":[],"name":"Extend Pseudopod","actions":"ONE-ACTION","level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"Your companion has learned its advanced maneuver through nimble or savage advancement.","access":"","description":"Your chair lengthens itself, granting its pseudopod [Strike](link_action_19856) the [reach 10 feet](link_trait_4173) trait until the beginning of your next turn.","special":"","type":"action","meta_data":{"source":{"book":"Treasure Vault (Remastered)","page":"107","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"traits":[],"content_source_id":16,"version":"1.0"}],"spells":null,"deprecated":false,"abilities_added":[],"experience":0,"hp_current":0,"hp_temp":0,"stamina_current":0,"resolve_current":0,"operation_data":null,"type":"creature"},"attack_operation_id":"d85a1f8e-a36b-4c34-ba83-01b58455e3e8"},"seed_counts":{"item":1118,"creature":1,"trait":24},"chair_counts":{"item":1119,"creature":2,"trait":24}}$successor$::jsonb;
  successor_ok boolean;
  actual_creature_count bigint;
  source_spec jsonb; dependency jsonb; patch jsonb; actual jsonb; expected jsonb;
  captured_sources jsonb:='{}'; captured_dependencies jsonb:='{}'; captured_items jsonb;
  inserted_rows jsonb:='{}'; inserted_ids bigint[]:='{}'; item_row public.item%rowtype;
  terminal_count integer:=0; row_count integer; actual_count bigint; actual_trait_count bigint; current_hashes jsonb; before_count jsonb;
begin
  lock table public.content_update in share mode;
  lock table public.item in share row exclusive mode;
  lock table public.creature in share mode;
  lock table public.trait in share mode;
  -- Lock dependencies before their source rows to avoid the ordinary child/cache write order inversion.
  for dependency in select value from jsonb_array_elements(spec->'dependencies') order by value->>'table',(value->>'id')::bigint loop
    if dependency->>'table'='trait' then select to_jsonb(t)||jsonb_build_object('uuid',t.uuid::text) into actual from public.trait t where t.id=(dependency->>'id')::bigint for share;
    elsif dependency->>'table'='ability_block' then select to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text) into actual from public.ability_block a where a.id=(dependency->>'id')::bigint for share;
    elsif dependency->>'table'='creature' then select to_jsonb(c)||jsonb_build_object('uuid',c.uuid::text) into actual from public.creature c where c.id=(dependency->>'id')::bigint for share;
    elsif dependency->>'table'='item' then select to_jsonb(i)||jsonb_build_object('uuid',i.uuid::text) into actual from public.item i where i.id=(dependency->>'id')::bigint for share;
    elsif dependency->>'table'='class' then select to_jsonb(c)||jsonb_build_object('uuid',c.uuid::text) into actual from public.class c where c.id=(dependency->>'id')::bigint for share;
    else raise exception 'Relic seeds unsupported dependency'; end if;
    if actual is null or jsonb_typeof(actual->'meta_data') is distinct from 'object'
      or exists(select 1 from jsonb_each(dependency->'expected') e where actual->e.key is distinct from e.value)
      or exists(select 1 from jsonb_each(dependency->'metadata') e where actual#>array['meta_data',e.key] is distinct from e.value)
      or exists(select 1 from jsonb_array_elements_text(dependency->'metadata_absent') k(key) where actual->'meta_data'?k.key)
      then raise exception 'Relic seeds dependency drift %:%',dependency->>'table',dependency->>'id'; end if;
    captured_dependencies:=jsonb_set(captured_dependencies,array[(dependency->>'table')||':'||(dependency->>'id')],actual-'{updated_at,search_tsv}'::text[],true);
  end loop;
  for source_spec in select value from jsonb_array_elements(spec->'sources') order by (value->>'id')::bigint loop
    select to_jsonb(s) into actual from public.content_source s where s.id=(source_spec->>'id')::bigint for update;
    if actual is null or jsonb_typeof(actual->'meta_data') is distinct from 'object'
      or exists(select 1 from jsonb_each(source_spec->'expected') e where actual->e.key is distinct from e.value)
      or exists(select 1 from jsonb_each(source_spec->'metadata_known_noncount') e where actual#>array['meta_data',e.key] is distinct from e.value)
      then raise exception 'Relic seeds source drift %',source_spec->>'id'; end if;
    captured_sources:=jsonb_set(captured_sources,array[source_spec->>'id'],actual-'updated_at',true);
  end loop;

  if exists(select 1 from public.content_update u where coalesce(u.status->>'state','PENDING') not in ('APPROVED','REJECTED') and (
    (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or (u.ref_id is null and u.data->>'name'=s#>>'{expected,name}')))
    or (u.type='item' and exists(select 1 from jsonb_array_elements(spec->'items') p where
      u.data->>'uuid'=p->>'uuid'
      or exists(select 1 from public.item i where i.uuid=(p->>'uuid')::bigint and (u.ref_id=i.id or u.data->>'id'=i.id::text))
      or ((u.content_source_id=16 or u.data->>'content_source_id'='16') and
        exists(select 1 from jsonb_array_elements(spec->'aliases') a where
          exists(select 1 from jsonb_array_elements_text(a->'names') n(name)
            where btrim(regexp_replace(lower(u.data->>'name'),'[^a-z0-9]+',' ','g')) like n.name||'%')
          or (coalesce(u.data#>>'{meta_data,source,url}','') ~* '^https?://2e[.]aonprd[.]com/Equipment[.]aspx[?]'
            and substring(lower(u.data#>>'{meta_data,source,url}') from '[?&]id=([0-9]+)') in(select jsonb_array_elements_text(a->'citation_ids')))))))
    or exists(select 1 from jsonb_array_elements(spec->'dependencies') d where u.type=d->>'queue_type' and
      (u.ref_id=(d->>'id')::bigint or u.data->>'id'=d->>'id' or u.data->>'uuid'=d->>'uuid'
        or ((u.content_source_id=(d->>'source')::bigint or u.data->>'content_source_id'=d->>'source') and u.data->>'name'=d->>'name')))
  )) then raise exception 'Relic seeds pending content requires review'; end if;

  if exists(select 1 from public.item i left join public.content_source s on s.id=i.content_source_id where
    (i.uuid in(select (p->>'uuid')::bigint from jsonb_array_elements(spec->'items') p)
      and (i.content_source_id<>16 or not exists(select 1 from jsonb_array_elements(spec->'items') p where p->>'uuid'=i.uuid::text and p->>'name'=i.name)))
    or (
      exists(select 1 from jsonb_array_elements(spec->'aliases') a where
        exists(select 1 from jsonb_array_elements_text(a->'names') n(name)
          where btrim(regexp_replace(lower(i.name),'[^a-z0-9]+',' ','g')) like n.name||'%')
        or (coalesce(i.meta_data#>>'{source,url}','') ~* '^https?://2e[.]aonprd[.]com/Equipment[.]aspx[?]'
          and substring(lower(i.meta_data#>>'{source,url}') from '[?&]id=([0-9]+)') in(select jsonb_array_elements_text(a->'citation_ids'))))
      and (i.content_source_id=16 or s.id is null or s.user_id is null)
      and not exists(select 1 from jsonb_array_elements(spec->'items') p where p->>'uuid'=i.uuid::text and p->>'name'=i.name and i.content_source_id=16)
    )
  ) then raise exception 'Relic seeds collision requires review'; end if;
  -- Validate every complete terminal owner before deciding whether this is a no-op replay.
  for patch in select value from jsonb_array_elements(spec->'items') loop
    select * into item_row from public.item where uuid=(patch->>'uuid')::bigint;
    if found then
      actual:=to_jsonb(item_row);
      if actual-'{id,created_at,updated_at,search_tsv}'::text[] is distinct from patch->'row'
        or item_row.id<=0 or jsonb_typeof(item_row.meta_data) is distinct from 'object'
        or exists(select 1 from jsonb_each((patch->'row')-'meta_data') e where actual->e.key is distinct from e.value)
        or exists(select 1 from jsonb_each(patch#>'{row,meta_data}') e where item_row.meta_data->e.key is distinct from e.value)
        or exists(select 1 from jsonb_array_elements_text(patch->'metadata_absent') k(key) where item_row.meta_data?k.key)
        then raise exception 'Relic seeds unreviewed terminal row %',patch->>'name'; end if;
      terminal_count:=terminal_count+1;
    end if;
  end loop;
  select count(*) into actual_count from public.item where content_source_id=16;
  select count(*) into actual_trait_count from public.trait where content_source_id=16;
  if actual_trait_count<>(spec#>>'{terminal_counts,trait}')::bigint then raise exception 'Relic seeds actual trait count drift'; end if;
  select count(*) into actual_creature_count from public.creature where content_source_id=16;
  before_count:=jsonb_build_object('item',captured_sources#>'{16,meta_data,counts,item}','creature',captured_sources#>'{16,meta_data,counts,creature}','trait',captured_sources#>'{16,meta_data,counts,trait}');
  if terminal_count=5 then
    -- Later releases are accepted only as complete, reviewed content and count tuples.
    with successor_settings as(select successor_spec as successor),
    chair_rows as(
 select i.id as item_id,c.id as creature_id,to_jsonb(i)-'{id,created_at,updated_at,search_tsv}'::text[] as item_row,
  to_jsonb(c)-'{id,created_at,updated_at,search_tsv}'::text[] as creature_row,
  successor#>'{chair,item}' as expected_item,
  jsonb_set(successor#>'{chair,creature}','{operations}',(select jsonb_agg(case when op->>'id'=successor#>>'{chair,attack_operation_id}'
    then jsonb_set(op,'{data,itemId}',to_jsonb(i.id),false) else op end order by ordinal)
    from jsonb_array_elements(successor#>'{chair,creature,operations}') with ordinality as a(op,ordinal)),false) as expected_creature
 from successor_settings left join public.item i on i.uuid=(successor#>>'{chair,item,uuid}')::bigint
 left join public.creature c on c.uuid=(successor#>>'{chair,creature,uuid}')::bigint
),
successor_state as(
 select coalesce((
  (select count(*)=5 and count(distinct i.id)=5 and bool_and((i.id>0 and
    to_jsonb(i)-'{id,created_at,updated_at,search_tsv}'::text[] is not distinct from seed) is true)
   from successor_settings cross join lateral jsonb_array_elements(successor->'seeds') seed
   left join public.item i on i.uuid=(seed->>'uuid')::bigint)
  and (select count(*)=24 from public.trait where content_source_id=16)
  and ((
    (select count(*)=1118 from public.item where content_source_id=16)
    and (select count(*)=1 from public.creature where content_source_id=16)
    and (select jsonb_build_object('item',meta_data::jsonb#>'{counts,item}','creature',meta_data::jsonb#>'{counts,creature}','trait',meta_data::jsonb#>'{counts,trait}')
      is not distinct from successor->'seed_counts' from public.content_source where id=16)
    and (select item_id is null and creature_id is null from chair_rows)
   ) or (
    (select count(*)=1119 from public.item where content_source_id=16)
    and (select count(*)=2 from public.creature where content_source_id=16)
    and (select jsonb_build_object('item',meta_data::jsonb#>'{counts,item}','creature',meta_data::jsonb#>'{counts,creature}','trait',meta_data::jsonb#>'{counts,trait}')
      is not distinct from successor->'chair_counts' from public.content_source where id=16)
    and (select cr.item_id>0 and cr.creature_id>0 and cr.item_row is not distinct from cr.expected_item and cr.creature_row is not distinct from cr.expected_creature from chair_rows cr)
   ))
 ),false) as passed from successor_settings
)
    select passed into successor_ok from successor_state;
    if exists(select 1 from public.content_update u where coalesce(u.status->>'state','PENDING') not in ('APPROVED','REJECTED') and (
    (u.type='item' and exists(select 1 from jsonb_array_elements((successor_spec->'seeds')||jsonb_build_array(successor_spec#>'{chair,item}')) p where
      u.data->>'uuid'=p->>'uuid' or exists(select 1 from public.item i where i.uuid=(p->>'uuid')::bigint and (u.ref_id=i.id or u.data->>'id'=i.id::text))
      or ((u.content_source_id=16 or u.data->>'content_source_id'='16') and u.data->>'name'=p->>'name')))
    or (u.type='creature' and (u.data->>'uuid'=successor_spec#>>'{chair,creature,uuid}'
      or exists(select 1 from public.creature c where c.uuid=(successor_spec#>>'{chair,creature,uuid}')::bigint and (u.ref_id=c.id or u.data->>'id'=c.id::text))
      or ((u.content_source_id=16 or u.data->>'content_source_id'='16') and u.data->>'name'=successor_spec#>>'{chair,creature,name}')))
  )) then raise exception 'Relic seeds successor pending content requires review'; end if;
    if not successor_ok then raise exception 'Relic seeds terminal count drift'; end if;
    return;
  end if;
  if terminal_count<>0 or actual_count<>(spec->>'baseline_item_count')::bigint or actual_creature_count<>(spec#>>'{baseline_counts,creature}')::bigint
    or exists(select 1 from public.item where uuid=(successor_spec#>>'{chair,item,uuid}')::bigint)
    or exists(select 1 from public.creature where uuid=(successor_spec#>>'{chair,creature,uuid}')::bigint)
    or before_count is distinct from spec->'baseline_counts'
    or jsonb_typeof(captured_sources#>'{16,meta_data,counts}') is distinct from 'object'
    then raise exception 'Relic seeds incomplete import or baseline count drift'; end if;
  select coalesce(jsonb_object_agg(i.id::text,md5((to_jsonb(i)-'{updated_at,search_tsv}'::text[])::text)),'{}') into captured_items from public.item i;
  for patch in select value from jsonb_array_elements(spec->'items') loop
    -- The baseline is the initial validated state, never a newly accepted trigger-mutated state.
    select coalesce(jsonb_object_agg(i.id::text,md5((to_jsonb(i)-'{updated_at,search_tsv}'::text[])::text)),'{}') into current_hashes from public.item i where not(i.id=any(inserted_ids));
    if current_hashes is distinct from captured_items then raise exception 'Relic seeds existing-item baseline changed'; end if;
    for actual in select to_jsonb(i)-'{updated_at,search_tsv}'::text[] from public.item i where i.id=any(inserted_ids) loop
      if actual is distinct from inserted_rows->(actual->>'id') then raise exception 'Relic seeds earlier inserted row changed'; end if;
    end loop;
    insert into public.item(name,bulk,level,rarity,description,"group",hands,size,craft_requirements,usage,meta_data,operations,content_source_id,version,uuid,price,traits,availability)
      select r.name,r.bulk,r.level,r.rarity,r.description,r."group",r.hands,r.size,r.craft_requirements,r.usage,r.meta_data,
        array(select value::json from jsonb_array_elements(patch#>'{row,operations}')),
        r.content_source_id,r.version,r.uuid,r.price,r.traits,r.availability from jsonb_populate_record(null::public.item,patch->'row') r
      returning * into item_row;
    get diagnostics row_count=row_count;
    if row_count<>1 then raise exception 'Relic seeds INSERT CAS failed'; end if;
    actual:=to_jsonb(item_row)-'{updated_at,search_tsv}'::text[];
    expected:=(patch->'row')||jsonb_build_object('id',item_row.id,'created_at',to_jsonb(item_row)->'created_at');
    if actual is distinct from expected then raise exception 'Relic seeds inserted full row drift'; end if;
    inserted_ids:=array_append(inserted_ids,item_row.id);
    inserted_rows:=jsonb_set(inserted_rows,array[item_row.id::text],expected,true);
  end loop;
  -- Direct SQL inserts do not maintain the edge uploader's cached count leaf.
  update public.content_source s set meta_data=jsonb_set(jsonb_set(s.meta_data::jsonb,'{counts,item}',spec#>'{terminal_counts,item}',false),'{counts,trait}',spec#>'{terminal_counts,trait}',false)
    where s.id=16 and (to_jsonb(s)-'updated_at') is not distinct from captured_sources->'16';
  get diagnostics row_count=row_count;
  if row_count<>1 then raise exception 'Relic seeds count CAS failed'; end if;
  captured_sources:=jsonb_set(jsonb_set(captured_sources,'{16,meta_data,counts,item}',spec#>'{terminal_counts,item}',false),'{16,meta_data,counts,trait}',spec#>'{terminal_counts,trait}',false);
  -- A final all-owner/dependency/source readback also catches later-trigger changes to earlier records.
  select coalesce(jsonb_object_agg(i.id::text,md5((to_jsonb(i)-'{updated_at,search_tsv}'::text[])::text)),'{}') into current_hashes from public.item i where not(i.id=any(inserted_ids));
  if current_hashes is distinct from captured_items then raise exception 'Relic seeds final existing-item baseline changed'; end if;
  select count(*) into row_count from public.item where id=any(inserted_ids);
  if row_count<>5 then raise exception 'Relic seeds inserted row missing'; end if;
  for actual in select to_jsonb(i)-'{updated_at,search_tsv}'::text[] from public.item i where i.id=any(inserted_ids) loop
    if actual is distinct from inserted_rows->(actual->>'id') then raise exception 'Relic seeds final inserted full row drift'; end if;
  end loop;
  for source_spec in select value from jsonb_array_elements(spec->'sources') loop
    select to_jsonb(s)-'updated_at' into actual from public.content_source s where s.id=(source_spec->>'id')::bigint;
    if actual is distinct from captured_sources->(source_spec->>'id') then raise exception 'Relic seeds final source baseline changed'; end if;
  end loop;
  for dependency in select value from jsonb_array_elements(spec->'dependencies') loop
    if dependency->>'table'='trait' then select to_jsonb(t)||jsonb_build_object('uuid',t.uuid::text) into actual from public.trait t where t.id=(dependency->>'id')::bigint;
    elsif dependency->>'table'='ability_block' then select to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text) into actual from public.ability_block a where a.id=(dependency->>'id')::bigint;
    elsif dependency->>'table'='creature' then select to_jsonb(c)||jsonb_build_object('uuid',c.uuid::text) into actual from public.creature c where c.id=(dependency->>'id')::bigint;
    elsif dependency->>'table'='item' then select to_jsonb(i)||jsonb_build_object('uuid',i.uuid::text) into actual from public.item i where i.id=(dependency->>'id')::bigint;
    else select to_jsonb(c)||jsonb_build_object('uuid',c.uuid::text) into actual from public.class c where c.id=(dependency->>'id')::bigint; end if;
    if (actual-'{updated_at,search_tsv}'::text[]) is distinct from captured_dependencies->((dependency->>'table')||':'||(dependency->>'id')) then raise exception 'Relic seeds final dependency baseline changed'; end if;
  end loop;
  select count(*) into actual_count from public.item where content_source_id=16;
  if actual_count<>(spec->>'terminal_item_count')::bigint then raise exception 'Relic seeds final item count drift'; end if;
  select count(*) into actual_trait_count from public.trait where content_source_id=16;
  if actual_trait_count<>(spec#>>'{terminal_counts,trait}')::bigint then raise exception 'Relic seeds final actual trait count drift'; end if;
  select count(*) into actual_creature_count from public.creature where content_source_id=16;
  if actual_creature_count<>(spec#>>'{terminal_counts,creature}')::bigint then raise exception 'Relic seeds final creature count drift'; end if;
  if exists(select 1 from public.content_update u where coalesce(u.status->>'state','PENDING') not in ('APPROVED','REJECTED') and (
    (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or (u.ref_id is null and u.data->>'name'=s#>>'{expected,name}')))
    or (u.type='item' and exists(select 1 from jsonb_array_elements(spec->'items') p where
      u.data->>'uuid'=p->>'uuid'
      or exists(select 1 from public.item i where i.uuid=(p->>'uuid')::bigint and (u.ref_id=i.id or u.data->>'id'=i.id::text))
      or ((u.content_source_id=16 or u.data->>'content_source_id'='16') and
        exists(select 1 from jsonb_array_elements(spec->'aliases') a where
          exists(select 1 from jsonb_array_elements_text(a->'names') n(name)
            where btrim(regexp_replace(lower(u.data->>'name'),'[^a-z0-9]+',' ','g')) like n.name||'%')
          or (coalesce(u.data#>>'{meta_data,source,url}','') ~* '^https?://2e[.]aonprd[.]com/Equipment[.]aspx[?]'
            and substring(lower(u.data#>>'{meta_data,source,url}') from '[?&]id=([0-9]+)') in(select jsonb_array_elements_text(a->'citation_ids')))))))
    or exists(select 1 from jsonb_array_elements(spec->'dependencies') d where u.type=d->>'queue_type' and
      (u.ref_id=(d->>'id')::bigint or u.data->>'id'=d->>'id' or u.data->>'uuid'=d->>'uuid'
        or ((u.content_source_id=(d->>'source')::bigint or u.data->>'content_source_id'=d->>'source') and u.data->>'name'=d->>'name')))
  )) then raise exception 'Relic seeds final curator guard changed'; end if;
end $missing$;
$historical_original_dual$;
end $historical_dual$;
